const prefix='benchmark-results/heavy-scenes/',name='visibility-support',date='2026-10-26',destination=`docs/benchmarks/${name}-${date}.json`
const base='55f576522a66ce968dd8872a5f56b121ab23ad54',pathRoot='src/core/renderables/DetailedRingStreamingSystem/',provenance=[]
const hash=b=>createHash('sha256').update(b).digest('hex')
const decode=b=>b[0]===255&&b[1]===254?b.subarray(2).toString('utf16le'):b.toString('utf8').replace(/^\uFEFF/,'')
const normalize=t=>t.replaceAll('\r\n','\n'),equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b)
