async function source(path,json=true){const b=await readFile(path);provenance.push({path,bytes:b.length,sha256:hash(b)});const t=decode(b);requireThat(!t.includes('\0'),'NUL in '+path);return json?JSON.parse(t):t}
function stats(samples,summary,count=samples.length){
