  requireThat(s.length===count&&summary.count===count&&s.every(x=>Number.isFinite(x)&&x>=0)&&s[Math.ceil(count*.5)-1]===summary.p50&&s[Math.ceil(count*.95)-1]===summary.p95&&s.at(-1)===summary.max,'Invalid raw samples/statistics')
