    'bool dustUnshadowed = uDustPlanetRadius <= 0.0 && uRingBandEnabled < 0.5;\n          float litTau = 0.0;')
  shadows = replace(shadows,
    'if (uDustPlanetRadius <= 0.0 && uRingBandEnabled < 0.5) {\n              litTau += contrib;\n            } else {',
    'if (!dustUnshadowed) {')
  shadows = replace(shadows, 'float litFrac = tau > 0.0 ? litTau / tau : 1.0;',
    'float litFrac = !dustUnshadowed && tau > 0.0 ? litTau / tau : 1.0;')
  return [['guardSmallTauExit', guardedExit], ['uniformLoopLimit', loop], ['angularExplicitLod', angular], ['skipUnusedSunPhase', sun], ['skipUnshadowedLitTau', shadows]]
}

